function initials(name){ return String(name).split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(); }
function fallbackHash(s){ let h1=0xdeadbeef^s.length,h2=0x41c6ce57^s.length;for(let i=0,ch;i<s.length;i++){ch=s.charCodeAt(i);h1=Math.imul(h1^ch,2654435761);h2=Math.imul(h2^ch,1597334677)}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return Array.from({length:4},(_,i)=>((i%2?h2:h1)>>>0).toString(16).padStart(8,'0')).join('');}
async function sha256(s){ try { const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)); return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''); } catch { return fallbackHash(s); } }

