function iconColor(i){ return ['#2563eb','#0ca678','#7048e8','#f59f00','#e64980'][i%5]; }
function pill(t,type='green'){ return `<span class="pill ${type}">${esc(t)}</span>`; }
function statusPill(s){ const v=String(s); const type=/published|approved|active|effective|current|paid|success|healthy|completed/i.test(v)?'green':/critical|failed|expired|rejected|overdue|hold/i.test(v)?'red':/pending|review|planned|warning|partial|attention/i.test(v)?'amber':/draft|progress|scheduled|beta/i.test(v)?'blue':'gray'; return pill(v,type); }
function progress(n,type=''){ return `<div class="progress ${type}"><span style="width:${Math.max(0,Math.min(100,+n||0))}%"></span></div>`; }
function btn(label,kind='',action=''){ return `<button class="btn ${kind}" ${action?`onclick="${action}"`:''}>${label}</button>`; }
function pageHead(title,desc,actions=''){ return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`; }
function kpi(label,value,sub,icon='◉',tone='blue'){ return `<div class="card kpi-card"><div class="kpi-top"><div class="kpi-icon ${tone}">${icon}</div><span class="tiny muted">KPI</span></div><strong>${value}</strong><span>${label}</span><small>${sub}</small></div>`; }
function card(title,body,sub='',actions=''){ return `<section class="card"><div class="card-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${actions}</div><div class="card-body">${body}</div></section>`; }
function table(headers,rows){ return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`; }
function meta(k,v){ return `<div class="meta"><small>${esc(k)}</small><strong>${v}</strong></div>`; }
function empty(title,desc,icon='✓'){ return `<div class="empty"><div class="big">${icon}</div><strong>${title}</strong><p>${desc}</p></div>`; }
function lineChart(points=[18,25,31,42,58,71,82],second=[10,14,18,27,35,48,61]){ const w=660,h=220,p=32; const coords=a=>a.map((v,i)=>`${p+i*(w-2*p)/(a.length-1)},${h-p-v*(h-2*p)/100}`).join(' '); return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><g>${[25,50,75,100].map(v=>`<line x1="${p}" y1="${h-p-v*(h-2*p)/100}" x2="${w-p}" y2="${h-p-v*(h-2*p)/100}" stroke="#e8edf2"/><text x="2" y="${h-p-v*(h-2*p)/100+4}" fill="#98a2b3" font-size="9">${v}</text>`).join('')}</g><polyline points="${coords(points)}" fill="none" stroke="#20b85a" stroke-width="3"/><polyline points="${coords(second)}" fill="none" stroke="#3978e8" stroke-width="2.5"/><g>${points.map((v,i)=>{const [x,y]=coords(points).split(' ')[i].split(',');return `<circle cx="${x}" cy="${y}" r="3" fill="#fff" stroke="#20b85a" stroke-width="2"/>`}).join('')}</g></svg>`; }
function donut(value=78,label='Posture'){ return `<div class="donut" style="--pct:${value}"><div><strong>${value}%</strong><span>${label}</span></div></div>`; }
function heatmap(){ let cells=''; for(let r=5;r>=1;r--) for(let c=1;c<=5;c++){const v=(r*c)%7; const cls=r*c>=18?'heat-red':r*c>=10?'heat-amber':'heat-green'; cells+=`<div class="heat ${cls}">${v||''}</div>`;} return `<div class="heatmap"><div class="heat-grid">${cells}</div><div class="tiny muted" style="margin-top:8px">Likelihood → &nbsp;&nbsp; Impact ↑</div></div>`; }
function savePage(p){ state.page=p; safeSet(`gw_page_${account.id}`,p); }
function go(p){ savePage(p); render(); window.scrollTo({top:0,behavior:'smooth'}); $('#sidebar')?.classList.remove('open'); }
window.go=go;
function toast(msg){ const t=$('#toast'); if(!t)return; t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400); }
window.toast=toast;
function modal(title,body){ $('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').classList.add('show'); }
function closeModal(){ $('#modal').classList.remove('show'); }
window.closeModal=closeModal;
function navRender(){ const n=$('#nav'); n.innerHTML=navConfig().map(([title,items])=>`<div class="nav-section"><div class="nav-title">${title}</div>${items.map(([id,ico,label,badge])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-ico">${ico}</span><span>${label}</span>${badge?`<span class="nav-badge">${badge}</span>`:''}</button>`).join('')}</div>`).join(''); $$('[data-page]',n).forEach(b=>b.onclick=()=>go(b.dataset.page)); }
function shell(){ document.documentElement.lang=store.lang; document.documentElement.dir=store.lang==='ar'?'rtl':'ltr'; $('#contextName').textContent=account.context;$('#contextScope').textContent=`${account.orgType} · ${account.scope}`;$('#contextRole').textContent=account.role;$('#personaName').textContent=account.name;$('#personaRole').textContent=account.role;$('#personaAvatar').textContent=initials(account.name);$('#personaAvatar').style.background=account.color;$('#langBtn').textContent=store.lang==='ar'?'AR':'EN'; navRender(); }
