function groupDashboard(){ return `${pageHead('Group Executive Dashboard','Consolidated assurance across subsidiaries with inherited governance and isolated entity workspaces.',btn('Add Subsidiary','primary',"openSimpleForm('Onboard Subsidiary','entity')")+btn('Board Pack','',"go('reports')"))}${roleBanner('Al Noor Holding Group Control Plane','Parent-mandated controls, shared services and subsidiary scorecards consolidate without exposing peer-entity restricted data.','82.4%','integrated assurance score')}<div class="grid kpi">${kpi('Legal Entities','8','21 operational branches','◫','blue')}${kpi('Compliance Posture','82.4%','+3.1 this quarter','§','green')}${kpi('High / Critical Risks','12','4 reduced this month','△','red')}${kpi('Open Audit Findings','18','6 overdue','◎','amber')}</div><div class="grid two top-gap">${card('Integrated assurance trend',lineChart([56,61,66,70,74,79,82],[42,47,49,55,59,64,70]),'Group compliance and risk treatment')}${card('Subsidiary scorecards',`<div class="score-list">${[['Saudi Technology Services',91],['Jordan Operations',86],['Healthcare Division',78],['Retail Network',74],['Shared Services',89]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'Entity ranking and trend')}</div><div class="grid three top-gap">${card('Residual risk heatmap',heatmap(),'Group residual risk distribution')}${card('Shared control effectiveness',`<div class="score-list">${[['Identity & Access',88],['Cloud Security',82],['Supplier Assurance',73],['Privacy Governance',79],['Resilience',86]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'Parent-mandated controls')}${card('Executive attention',attentionFeed(),'Decisions and escalations')}</div>`; }
function orgDashboard(){ const branch=account.role==='Branch Admin'; return `${pageHead(branch?'Branch Dashboard':'Organization Dashboard',branch?'Local GRC activities and evidence for the assigned branch.':'Enterprise GRC posture across the organization and its branches.',btn('Create Action','primary',"openSimpleForm('Create Action','task')"))}${roleBanner(branch?'Madinah Branch Assurance Workspace':'OmniOps Integrated Assurance','Role-scoped dashboard showing standards, risks, implementations, evidence, audits and actions. Peer branches remain isolated.',branch?'78%':'84%','overall GRC posture')}<div class="grid kpi">${kpi('Enabled Frameworks',branch?'3':'5','Package entitlement active','§','blue')}${kpi('Controls Implemented',branch?'74 / 93':'172 / 214','Evidence-backed coverage','⌘','green')}${kpi('High Risks',branch?'4':'9','Treatments monitored','△','red')}${kpi('Open Actions',branch?'11':'27','Due within 30 days','✓','amber')}</div><div class="grid two top-gap">${card('Compliance progress',lineChart([48,55,61,67,73,79,84],[34,40,47,53,59,65,72]),'Implementation and evidence maturity')}${card('Framework posture',`<div class="score-list">${MOCK.standards.slice(0,4).map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(parseInt(x[3]))}<strong>${x[3]}</strong></div>`).join('')}</div>`,'Enabled standards')}</div><div class="grid three top-gap">${card('Risk heatmap',heatmap(),'Inherent and residual ratings')}${card('Audit status',attentionFeed([['Identity & Access Audit','Fieldwork','68%','High'],['Third-Party Risk Audit','Planning','22%','Medium'],['Backup & Resilience','Final','3 findings','Low']]),'Current assurance engagements')}${card('My work',attentionFeed(),'Due and overdue items')}</div>`; }
function documentDashboard(){ const pending=store.docs.filter(d=>d.status==='Pending Approval').length, pub=store.docs.filter(d=>d.status==='Published').length, hold=store.docs.filter(d=>d.legalHold).length; return `${pageHead('Enterprise Document Governance','Author, import, control, approve, publish, acknowledge, retain and audit enterprise GRC documents.',btn('Create Document','primary',"go('create-document')")+btn('Import Files','',"go('import-documents')"))}${roleBanner('Controlled Document Lifecycle','The mock demonstrates persona-based permissions, concurrency locks, semantic versions, e-signatures, acknowledgements, retention and immutable event history.',`${pub}/${store.docs.length}`,'documents published')}<div class="grid kpi">${kpi('Controlled Documents',store.docs.length,'All governed types','▤','blue')}${kpi('Pending Approval',pending,'Sequential approval queue','✓','amber')}${kpi('Acknowledgement Rate','91%','Assigned staff','✎','green')}${kpi('Legal Holds',hold,'WORM freeze active','♜','red')}</div><div class="workflow"><div class="workflow-step done">Draft</div><div class="workflow-arrow">→</div><div class="workflow-step ${pending?'active':''}">Under Review</div><div class="workflow-arrow">→</div><div class="workflow-step ${pending?'active':''}">Pending Approval</div><div class="workflow-arrow">→</div><div class="workflow-step ${pub?'done':''}">Published</div></div><div class="grid three top-gap">${card('Approval queue',store.docs.filter(d=>d.status==='Pending Approval').map(d=>`<div class="feed-item"><div class="feed-icon">✓</div><div><strong>${esc(d.title)}</strong><small>${d.code} · v${d.version}</small></div>${statusPill(d.status)}</div>`).join('')||empty('No pending approvals','The queue is clear.'),'Documents awaiting e-signature',btn('Open approvals','small',"go('approvals')"))}${card('Review & retention',attentionFeed([['Information Security Policy','Review due','30 Sep','Medium'],['Audit Report','Legal hold active','No disposal','Critical'],['Access Procedure','Approval SLA','2 days','High']]),'Lifecycle attention')}${card('Recent immutable activity',store.logs.slice(0,5).map(l=>`<div class="feed-item"><div class="feed-icon">#</div><div><strong>${esc(l.event)} · ${esc(l.document)}</strong><small>${esc(l.user)} · ${dateFmt(l.at)}</small></div></div>`).join(''),'Cryptographically linked actions')}</div>`; }
function staffDashboard(){ const docs=store.docs.filter(d=>d.status==='Published'),pending=docs.filter(d=>!d.acknowledgements?.some(a=>a.email===account.email));return `${pageHead('My Acknowledgements','Read and digitally acknowledge policies assigned to you.')}${roleBanner('Employee Policy Center','Only published documents assigned to your audience are visible. Editing, approval and retention controls are not available.',pending.length,'mandatory sign-offs pending')}<div class="grid kpi">${kpi('Assigned Policies',docs.length,'Published and current','▤','blue')}${kpi('Pending',pending.length,'Requires signature','✎','amber')}${kpi('Completed',docs.length-pending.length,'Audit evidence recorded','✓','green')}${kpi('Overdue',0,'No overdue items','!','green')}</div><div class="grid three top-gap">${docs.map(d=>ackCard(d)).join('')}</div>`; }
function approverDashboard(){ const q=store.docs.filter(d=>['Under Review','Pending Approval'].includes(d.status));return `${pageHead('Approval Workspace','Review document content, versions, comments and cryptographically sign approved documents.',btn('Open Approval Queue','primary',"go('approvals')"))}${roleBanner('Segregated Compliance Approval','Approvers cannot approve documents they own. Every approval records identity, role, timestamp, session, network origin and verification hash.',q.length,'documents awaiting decision')}<div class="grid kpi">${kpi('Approval Queue',q.length,'Sequential workflow','✓','amber')}${kpi('Signed This Month',6,'All hash verified','#','green')}${kpi('Rejected / Returned',1,'Owner notified','↩','red')}${kpi('SLA Achieved','96%','Target 95%','◷','blue')}</div>${card('Documents awaiting approval',q.length?table(['Document','Version','Owner','Classification','Status','Action'],q.map(d=>`<tr><td><div class="title">${esc(d.title)}</div><div class="sub mono">${d.code}</div></td><td>${d.version}</td><td>${esc(d.owner)}</td><td>${statusPill(d.classification)}</td><td>${statusPill(d.status)}</td><td>${btn('Review & Sign','small primary',`reviewApproval('${d.id}')`)}</td></tr>`)):empty('Queue clear','There are no documents awaiting approval.'),'Sequential compliance approval')}</div>`; }
function auditorDashboard(){ const published=store.docs.filter(d=>d.status==='Published');return `${pageHead('External Audit Room','Time-bound, read-only access to selected evidence, published documents, signatures and immutable activity logs.',btn('Export Audit Package','primary',"exportAuditPackage()"))}${roleBanner('Global Bank ISO 27001 Audit Room','This persona can inspect approved artifacts and verification hashes but cannot edit, approve, acknowledge, delete or release legal holds.',published.length,'approved artifacts in scope')}<div class="grid kpi">${kpi('Evidence Artifacts',published.length,'Selected audit scope','▤','blue')}${kpi('Signatures Verified',published.reduce((n,d)=>n+(d.approvals?.length||0),0),'SHA-256 records','#','green')}${kpi('Legal Holds',store.docs.filter(d=>d.legalHold).length,'Visible and protected','♜','red')}${kpi('Access Expires','14 days','Temporary external role','◷','amber')}</div><div class="grid two top-gap">${card('Audit package contents',published.map(d=>`<div class="feed-item"><div class="feed-icon">▤</div><div><strong>${esc(d.title)}</strong><small>${d.code} · v${d.version} · ${d.classification}</small></div>${statusPill(d.status)}</div>`).join(''),'Read-only controlled documents')}${card('Audit trail assurance',`<div class="score-list">${[['Artifact hashes present',100],['Approval identity captured',100],['Network origin captured',100],['Version lineage complete',100],['Retention assigned',100]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'Verification readiness')}</div>`; }
function partnerDashboard(){ return `${pageHead('Consulting Partner Portfolio','Manage isolated client workspaces, engagements, consultants, private content, renewals and transfers.',btn('Create Client Workspace','primary',"openSimpleForm('Create Client Workspace','client')"))}${roleBanner('GRC Consulting Partners','One account switches among fully isolated client workspaces. Private methodologies and reusable content remain within the partner library.','8','active client workspaces')}<div class="grid kpi">${kpi('Active Clients','8','2 onboarding','▥','blue')}${kpi('Engagements On Track','11 / 13','84.6%','◈','green')}${kpi('Consultant Utilization','76%','3 resources available','♙','violet')}${kpi('Renewal Pipeline','SAR 1.8M','Next 120 days','¤','amber')}</div><div class="grid two top-gap">${card('Client portfolio',`<div class="score-list">${[['OmniOps',84],['Hayat National Hospitals',79],['Eteqan Projects',71],['Al Noor Group',88],['NourNet',82]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'Assurance score by isolated workspace')}${card('Engagement attention',attentionFeed([['OmniOps evidence review','ISO 27001 + SOC 2','Tomorrow','High'],['Eteqan PDPL workshop','Delivery','03 Aug','Medium'],['HNH internal audit','Assurance','06 Aug','High'],['Client workspace transfer','Commercial','14 Aug','Medium']]),'Portfolio actions')}</div>`; }
function franchiseDashboard(){ const isLoc=account.role==='Franchisee Admin', actionTitle=isLoc?'Submit Evidence':'Onboard Franchisee';return `${pageHead(isLoc?'Location Dashboard':'Franchise Network Dashboard',isLoc?'Local compliance, evidence and actions for the assigned franchise location.':'Mandatory controls, exception governance, lifecycle and scorecards across the franchise network.',btn(actionTitle,'primary',`openSimpleForm('${actionTitle}','franchise')`))}${roleBanner(isLoc?'RetailCo — Riyadh North':'RetailCo Franchise Network',isLoc?'Franchisee data is isolated; franchisor visibility is limited to mandated governance and agreed scorecard data.':'Franchisor oversight across regions, franchisees and locations with central or mixed billing.',isLoc?'76%':'81%','compliance score')}<div class="grid kpi">${kpi(isLoc?'Local Controls':'Active Locations',isLoc?'46 / 58':'124','Mandatory baseline','⌘','blue')}${kpi('Non-Compliant',isLoc?'7':'18','Automatic escalation','!','red')}${kpi('Open Exceptions',isLoc?'2':'13','Workflow controlled','↩','amber')}${kpi('Evidence Current',isLoc?'82%':'86%','Validity monitored','▤','green')}</div><div class="grid two top-gap">${card(isLoc?'Local control status':'Region scorecards',`<div class="score-list">${(isLoc?[['Access Control',82],['Physical Security',74],['Privacy',88],['Business Continuity',68]]:[['Central Region',88],['Western Region',84],['Eastern Region',80],['Northern Region',73],['Southern Region',78]]).map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'Governance performance')}${card('Network attention',attentionFeed([['Riyadh North evidence expiry','Mandatory Control','3 days','High'],['Jeddah location exception','Approval','Overdue','Critical'],['New franchisee onboarding','Lifecycle','07 Aug','Medium'],['Quarterly network audit','Audit','14 Aug','Medium']]),'Automated compliance alerts')}</div>`; }
function dashboardPage(){
 if(/Service Desk|Support Coordinator|Support Manager|Post-Sales Customer Success/i.test(account.role))return itsmDashboardPage();
 if(/Marketplace Curator|Pre-Sales Manager/i.test(account.role))return marketplaceFocusedDashboard();
 if(/Wisdom Eye|Security Analyst/i.test(account.role))return wisdomEyePage();
 if(/Finance Manager|Billing Admin|Branch Finance User/i.test(account.role))return account.portal==='saas'?billingDashboard():billingCenterPage();
 if(/HR Manager|Branch HR User/i.test(account.role))return peopleDashboard();
 if(/Risk Manager/i.test(account.role))return riskPage();
 if(account.portal==='saas')return platformDashboard(); if(account.portal==='holding')return groupDashboard(); if(['multibranch','branch'].includes(account.portal))return orgDashboard(); if(account.portal==='document'){if(account.role==='Staff Employee')return staffDashboard();if(account.role==='Compliance Approver')return approverDashboard();return documentDashboard();} if(account.portal==='auditor')return auditorDashboard(); if(account.portal==='partner')return partnerDashboard(); if(account.portal==='franchise')return franchiseDashboard(); return orgDashboard();
}
