function usersPage(scope='all'){ const title=scope==='branch'?'Branch Users':scope==='org'?'Organization Users':'SaaS Admin Users'; const rows=MOCK.users.filter((_,i)=>scope==='all'?i<3:scope==='branch'?i>=2:i<2);return `${pageHead(title,'Lifecycle, role assignment, session control, MFA and entity-scoped access.',btn('Invite User','primary',"openSimpleForm('Invite User','user')")+btn('Bulk Actions','',"toast('Select users to continue')"))}<div class="grid kpi">${kpi('Active Users',scope==='all'?'12':scope==='org'?'84':'428','MFA coverage 96%','♙','green')}${kpi('Privileged Roles',scope==='all'?'5':'27','Monthly review current','♟','violet')}${kpi('Dormant Accounts','3','90+ days inactive','◷','amber')}${kpi('Locked Sessions','1','Security review open','!','red')}</div><section class="card top-gap"><div class="toolbar"><input placeholder="Search user, email or organization"><select><option>All roles</option><option>Admin</option><option>Auditor</option><option>Regular User</option></select><select><option>All statuses</option><option>Active</option><option>Suspended</option></select></div>${table(['Name','Email','Organization / Branch','Role','Status','Last Login','Actions'],rows.map(x=>`<tr><td><div class="title">${x[0]}</div></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${statusPill(x[4])}</td><td>${x[5]}</td><td><div class="btn-row">${btn('Reset Password','sm',"toast('Reset link generated')")}${btn('Force Logout','sm',"toast('Sessions revoked')")}${btn('Deactivate','sm red',"toast('Deactivation requires approval')")}</div></td></tr>`))}</section>`; }
function marketplacePage(){ const modules=(D.modules||[]).slice(0,16);return `${pageHead('Module Marketplace','Govern product modules, maturity, dependencies, packages and controlled add-on activation.',btn('Add Module','primary',"openSimpleForm('Add Module','module')")+btn('Create Bundle','',"openSimpleForm('Create Bundle','bundle')"))}<div class="notice amber">Commercial entitlement and technical release are separate. Beta or partially complete modules remain clearly labelled and require feature-flag approval.</div><div class="grid three top-gap">${modules.map((m,i)=>`<div class="card pad"><div class="split"><div class="kpi-icon" style="--icon-color:${iconColor(i)}">${['▦','△','◎','▤','✦'][i%5]}</div>${statusPill(m['Current Maturity']||m['Maturity']||'Planned')}</div><h3>${esc(m['Module / Capability']||m['Module']||'GRC Module')}</h3><p class="small muted">${esc(m['Business Purpose']||m['Description']||'Governed platform capability with role-based access and audit history.')}</p><div class="tag-row"><span class="tag">${esc(m['Commercial Model']||'Entitled')}</span><span class="tag">${esc(m['Readiness Phase']||'Roadmap')}</span></div><div class="btn-row top-gap">${btn('Configure','sm',"toast('Module configuration opened')")}${btn('Entitlements','sm blue',"toast('Entitlement matrix opened')")}</div></div>`).join('')}</div>`; }
