function securityPage(){ const nfr=(D.nfr||[]).filter(r=>/Security|Privacy|Backup|Resilience|Observability|Identity/i.test(Object.values(r).join(' '))).slice(0,16);return `${pageHead('Platform Security & Operations','Operate GRC Wisdom as a resilient, privacy-aware and auditable enterprise SaaS platform.',btn('Generate Assurance Pack','primary',"toast('Customer security assurance pack generated')")+btn('Security Events','',"toast('Security event console opened')"))}${roleBanner('OCI Riyadh Trust Posture','Layered safeguards cover identity, tenant isolation, edge protection, application security, encryption, immutable logging, privacy and resilience.','A','target enterprise trust grade')}<div class="grid four">${(nfr.length?nfr:[{Requirement:'Privileged MFA','Target / Rule':'Mandatory'},{Requirement:'Encryption at rest','Target / Rule':'Database, object and backups'},{Requirement:'Tenant isolation','Target / Rule':'No cross-tenant access'},{Requirement:'Immutable audit trail','Target / Rule':'Protected change history'}]).map((r,i)=>`<div class="card pad"><div class="split"><div class="kpi-icon" style="--icon-color:${iconColor(i)}">✓</div>${pill('Required','green')}</div><h3>${esc(r['Requirement']||r['Control']||r['Category'])}</h3><p class="small muted">${esc(r['Target / Rule']||r['Target']||r['Description'])}</p><div class="tiny muted">Verification: ${esc(r['Verification']||'Security test and evidence')}</div></div>`).join('')}</div>`; }
function architecturePage(){ const row=(label,items)=>`<div class="arch-row"><div class="arch-label">${label}</div><div class="arch-services">${items.map(x=>`<div class="arch-box"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></div>`;return `${pageHead('OCI Riyadh Target Architecture','Proposed secure and scalable deployment for Saudi Arabia Central with entity-aware authorization and controlled recovery.',btn('Architecture Decisions','primary',"toast('Architecture decision log opened')")+btn('Threat Model','',"toast('Threat model opened')"))}${roleBanner('Saudi-Hosted SaaS Control Plane','Primary workload placement in OCI Riyadh with fault-domain resilience, encrypted data services, managed security controls and monitored DevSecOps.','RUH','primary deployment region')}<section class="card pad"><div class="architecture">${row('Users & Identity',[['Responsive Web','Desktop and mobile browser'],['Federation','SAML · OIDC · SCIM'],['Privileged Access','MFA · JIT · break-glass'],['External Access','Time-bound auditor/vendor roles']])}${row('Edge & Ingress',[['OCI DNS','Managed authoritative DNS'],['OCI WAF','OWASP · bot · geo rules'],['Load Balancer','TLS · health checks'],['API Gateway','OAuth2 · quotas · validation']])}${row('Application Plane',[['OKE / Containers','Stateless web and APIs'],['Workflow Service','Approvals · jobs · escalations'],['Document Service','Versioning · preview · AV scan'],['Integration Workers','Webhooks · connectors · retries']])}${row('Data Plane',[['Relational Database','Tenant/entity context · backups'],['Object Storage','Documents · evidence · reports'],['Search Index','Authorized full-text search'],['Cache / Queue','Performance · async work']])}${row('Security Services',[['OCI IAM','Compartments · policies'],['OCI Vault','Secrets · CMKs · rotation'],['Cloud Guard','Threat and posture signals'],['Security Zones','Prevent insecure configuration']])}${row('Operations & DR',[['Logging & Audit','Application and security events'],['Monitoring & APM','SLO · traces · alerts'],['DevSecOps','SAST · SCA · DAST · signing'],['Recovery','Encrypted backup · restore tests']])}</div></section><div class="grid three top-gap">${card('Tenant Isolation Models',attentionFeed([['Shared service + logical isolation','Tenant/entity keys','Default','Low'],['Schema / database per tenant','Enhanced isolation','Add-on','Medium'],['Dedicated environment','Separate application and data plane','Premium','High']]),'Package and regulatory selection')}${card('Document Security Pipeline',attentionFeed([['Validate & quarantine','File type and malware checks','Step 1','Low'],['Encrypt & classify','Object keys and metadata','Step 2','Low'],['Index safely','Authorized text extraction','Step 3','Low'],['Controlled preview','Short-lived URL and watermark','Step 4','Low']]),'Ingestion before availability')}${card('NFR Targets',`<div class="score-list">${[['Assurance uptime',99.9],['Core pages ≤ 3 sec',95],['Privileged MFA',100],['Encryption coverage',100],['Quarterly restore test',100],['Arabic / RTL',100]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div>`,'BRD baseline')}</div>`; }
function brdPage(){ const reqs=D.requirements||[];return `${pageHead('BRD Traceability & Delivery Roadmap','Browse the 156-requirement baseline, six gated phases, owners, priorities and acceptance criteria.',btn('Export Backlog','primary',"toast('BRD backlog export prepared')"))}<div class="stat-strip"><div><small>Total Requirements</small><strong>${reqs.length}</strong></div><div><small>P0 / Must</small><strong>${reqs.filter(r=>r.Priority==='P0').length}</strong></div><div><small>Functional Modules</small><strong>${(D.modules||[]).length}</strong></div><div><small>Delivery Phases</small><strong>${(D.phases||[]).length}</strong></div><div><small>Planning Horizon</small><strong>18 months</strong></div></div><div class="grid three">${(D.phases||[]).map((p,i)=>`<div class="card pad"><div class="split"><div class="kpi-icon">${i}</div>${pill(p['Phase']||`Phase ${i}`,'blue')}</div><h3>${esc(p['Phase Name']||p['Name'])}</h3><p class="small muted">${esc(p['Objective'])}</p><div class="meta-grid">${meta('Start',String(p['Proposed Start']||p['Start']).slice(0,10))}${meta('End',String(p['Proposed End']||p['End']).slice(0,10))}${meta('Requirements',reqs.filter(r=>r.Phase===(p['Phase']||`Phase ${i}`)).length)}${meta('Gate',esc(p['Stage Gate']))}</div></div>`).join('')}</div><section class="card top-gap"><div class="toolbar"><input id="brdSearch" placeholder="Search ID, title, module or owner"><select id="brdPhase"><option value="">All phases</option>${(D.phases||[]).map(p=>`<option>${esc(p.Phase)}</option>`).join('')}</select><select id="brdPriority"><option value="">All priorities</option><option>P0</option><option>P1</option><option>P2</option></select><span class="spacer"></span><span id="brdCount" class="pill blue"></span></div><div id="brdTable"></div></section>`; }
function renderBrdRows(){ const q=($('#brdSearch')?.value||'').toLowerCase(),ph=$('#brdPhase')?.value||'',pr=$('#brdPriority')?.value||'';const a=(D.requirements||[]).filter(r=>(!q||Object.values(r).join(' ').toLowerCase().includes(q))&&(!ph||r.Phase===ph)&&(!pr||r.Priority===pr)).slice(0,120);$('#brdCount').textContent=`${a.length} shown`;$('#brdTable').innerHTML=table(['Requirement','Module','Phase','Priority','Owner','Acceptance Criteria'],a.map(r=>`<tr><td><div class="title mono">${r['Requirement ID']}</div><div class="sub">${esc(r['Requirement Title'])}</div></td><td>${esc(r['Module / Capability'])}</td><td>${pill(r.Phase,'blue')}</td><td>${pill(`${r.Priority} / ${r.MoSCoW}`,r.Priority==='P0'?'red':'amber')}</td><td>${esc(r['Proposed Owner'])}</td><td style="max-width:420px"><div class="sub">${esc(r['Acceptance Criteria'])}</div></td></tr>`)); }
function canEditDocs(){ return ['Compliance Manager','Organization Admin','Group Admin','Regional Admin','Branch Admin','Engagement Manager','Partner Owner','Franchisor Admin','Franchisee Admin'].includes(account.role); }
function canApproveDocs(){ return account.role==='Compliance Approver'; }
function canAcknowledge(){ return account.role==='Staff Employee'; }
function isAuditor(){ return account.role==='External Auditor'; }
function selectedDoc(){ return store.docs.find(d=>d.id===store.selectedDoc)||store.docs[0]; }
function setSelectedDoc(id){ store.selectedDoc=id;persist();render(); }
window.setSelectedDoc=setSelectedDoc;
function docActions(d){ const out=[btn('Preview','sm',`previewDocument('${d.id}')`)]; if(canEditDocs()){ out.push(btn(d.checkedOutBy===account.name?'Check In':'Check Out','sm',d.checkedOutBy===account.name?`openCheckin('${d.id}')`:`checkoutDocument('${d.id}')`)); out.push(btn('Edit','sm blue',`editDocument('${d.id}')`)); if(['Draft','Under Review'].includes(d.status))out.push(btn('Submit','sm primary',`submitApproval('${d.id}')`)); } if(canApproveDocs()&&d.status==='Pending Approval')out.push(btn('Review & Sign','sm primary',`reviewApproval('${d.id}')`)); if(canAcknowledge()&&d.status==='Published'&&!d.acknowledgements?.some(a=>a.email===account.email))out.push(btn('Acknowledge','sm primary',`acknowledgeDocument('${d.id}')`)); return `<div class="btn-row">${out.join('')}</div>`; }
function docDetail(d){ if(!d)return '';const approval=d.approvals?.[d.approvals.length-1];return `<div class="detail-title"><div class="doc-icon">${esc(d.category.slice(0,3).toUpperCase())}</div><div><h3>${esc(d.title)}</h3><div class="tiny mono muted">${d.code} · Version ${d.version}</div></div></div><div class="tag-row">${statusPill(d.status)}${statusPill(d.classification)}${d.legalHold?statusPill('Legal Hold'):''}${d.checkedOutBy?pill(`Checked out by ${d.checkedOutBy}`,'amber'):''}</div><div class="meta-grid">${meta('Owner',esc(d.owner))}${meta('Review Date',esc(d.reviewDate))}${meta('Retention',esc(d.retention))}${meta('Frameworks',esc((d.frameworks||[]).join(', ')))}${meta('Versions',d.versions?.length||1)}${meta('Acknowledgements',d.acknowledgements?.length||0)}</div><div class="btn-row top-gap">${docActions(d)}</div><h3 class="section-title top-gap">Lifecycle & Approval</h3><div class="timeline"><div class="timeline-row"><div class="timeline-dot">✓</div><div><strong>Created & Classified</strong><p>${dateFmt(d.createdAt)} · ${esc(d.owner)}</p></div></div><div class="timeline-row"><div class="timeline-dot">${d.versions?.length>1?'✓':'○'}</div><div><strong>Version Controlled</strong><p>${d.versions?.length||1} immutable snapshot(s)</p></div></div><div class="timeline-row"><div class="timeline-dot">${d.status==='Published'?'✓':d.status==='Pending Approval'?'•':'○'}</div><div><strong>Approval & Signature</strong><p>${approval?`${approval.name} · ${dateFmt(approval.at)}`:'Awaiting sequential approval'}</p></div></div><div class="timeline-row"><div class="timeline-dot">${d.status==='Published'?'✓':'○'}</div><div><strong>Published & Distributed</strong><p>${d.status==='Published'?`${d.acknowledgements?.length||0} acknowledgement(s) recorded`:'Not yet available to staff'}</p></div></div></div>${approval?`<div class="signature-card"><strong>Latest cryptographic sign-off</strong><div class="tiny muted">${approval.name} · ${approval.role} · ${approval.ip} · ${approval.session}</div><div class="hash">${approval.hash}</div></div>`:''}`; }
function documentsPage(){ const d=selectedDoc(),viewDocs=isAuditor()?store.docs.filter(x=>x.status==='Published'):store.docs;return `${pageHead(isAuditor()?'Read-Only Documents':'Documents & Policies',isAuditor()?'Controlled artifacts within the approved audit scope.':'Governed policies, procedures, evidence, contracts, reports and working files.',canEditDocs()?btn('Create Document','primary',"go('create-document')")+btn('Import Files','',"go('import-documents')"):btn('Export Selected','',"toast('Controlled read-only export prepared')"))}<div class="stat-strip"><div><small>Governed Documents</small><strong>${viewDocs.length}</strong></div><div><small>Pending Approval</small><strong>${viewDocs.filter(x=>x.status==='Pending Approval').length}</strong></div><div><small>Review Due</small><strong>${viewDocs.filter(x=>x.reviewDate!=='N/A').length}</strong></div><div><small>Published</small><strong>${viewDocs.filter(x=>x.status==='Published').length}</strong></div><div><small>Legal Hold</small><strong>${viewDocs.filter(x=>x.legalHold).length}</strong></div></div><section class="card"><div class="doc-layout"><aside class="doc-folders"><button class="btn primary" style="width:100%" ${canEditDocs()?'onclick="go(\'create-document\')"':'disabled'}>＋ New Document</button><div class="nav-title">Collections</div>${[['▣','All Documents',viewDocs.length],['▤','Policies',viewDocs.filter(x=>x.category==='Policy').length],['▥','Procedures',viewDocs.filter(x=>x.category==='Procedure').length],['◫','Evidence',viewDocs.filter(x=>x.category==='Evidence').length],['◎','Reports',viewDocs.filter(x=>x.category==='Report').length]].map((x,i)=>`<div class="folder ${i===0?'active':''}"><span>${x[0]}</span><span>${x[1]}</span><span class="count">${x[2]}</span></div>`).join('')}<div class="nav-title">Governance Views</div>${[['◷','Review Due',3],['✓','Pending Approval',viewDocs.filter(x=>x.status==='Pending Approval').length],['⚑','Legal Hold',viewDocs.filter(x=>x.legalHold).length],['⌁','Checked Out',viewDocs.filter(x=>x.checkedOutBy).length]].map(x=>`<div class="folder"><span>${x[0]}</span><span>${x[1]}</span><span class="count">${x[2]}</span></div>`).join('')}</aside><div class="doc-main"><div class="toolbar"><input id="docSearch" placeholder="Search full text, metadata or control mapping"><select><option>All document types</option><option>Policy</option><option>Procedure</option><option>Evidence</option><option>Report</option></select><select><option>All statuses</option><option>Draft</option><option>Pending Approval</option><option>Published</option></select><span class="spacer"></span>${pill('Full-text authorized','green')}</div>${table(['Document','Owner','Version','Status','Classification','Review','Lock'],viewDocs.map(x=>`<tr class="doc-row ${x.id===d?.id?'selected':''}" onclick="setSelectedDoc('${x.id}')"><td><div class="doc-name"><div class="doc-icon">${x.category.slice(0,3).toUpperCase()}</div><div><div class="title">${esc(x.title)}</div><div class="sub mono">${x.code} · ${esc((x.frameworks||[]).join(' · '))}</div></div></div></td><td>${esc(x.owner)}</td><td>${x.version}</td><td>${statusPill(x.status)}</td><td>${statusPill(x.classification)}</td><td>${esc(x.reviewDate)}</td><td>${x.checkedOutBy?pill('Locked','amber'):'—'}</td></tr>`))}</div><aside class="doc-detail">${docDetail(d)}</aside></div></section>`; }
function previewDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d)return;modal('Controlled Document Preview',`<div class="preview-sheet"><div class="watermark">${esc(d.classification.toUpperCase())} · ${d.code}</div><div class="tiny mono muted" style="text-align:center">${d.code} · Version ${d.version} · ${d.classification}</div><h1>${esc(d.title)}</h1><p style="text-align:center"><strong>Owner:</strong> ${esc(d.owner)} &nbsp; | &nbsp; <strong>Status:</strong> ${esc(d.status)}</p><hr>${d.content}</div><div class="btn-row top-gap" style="justify-content:flex-end">${btn('Generate Controlled Copy','',"toast('Watermarked controlled copy generated')")}${btn('Close','primary',"closeModal()")}</div>`); }
window.previewDocument=previewDocument;
async function checkoutDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canEditDocs())return;if(d.legalHold){toast('Document is under legal hold and cannot be changed');return;}if(d.checkedOutBy&&d.checkedOutBy!==account.name){toast(`Locked by ${d.checkedOutBy}`);return;}d.checkedOutBy=account.name;await logEvent('Check Out',d,{session:uid('SES')});persist();toast('Document checked out. Concurrent editing is locked.');render(); }
window.checkoutDocument=checkoutDocument;
function openCheckin(id){ const d=store.docs.find(x=>x.id===id);if(!d)return;modal('Check In Document',`<div class="notice">Checking in releases the concurrency lock and creates a permanent version snapshot.</div><div class="form-grid top-gap"><div class="field"><label>Version Update</label><select id="checkinType"><option value="minor">Minor (${d.version} → ${nextVersion(d.version,'minor')})</option><option value="major">Major (${d.version} → ${nextVersion(d.version,'major')})</option></select></div><div class="field"><label>Current Version</label><input value="${d.version}" disabled></div><div class="field full"><label>Summary of Changes</label><textarea id="changeSummary" placeholder="Describe the controlled changes"></textarea></div></div><div class="btn-row" style="justify-content:flex-end">${btn('Cancel','',"closeModal()")}${btn('Check In','primary',`checkinDocument('${id}')`)}</div>`); }
window.openCheckin=openCheckin;
function nextVersion(v,type){ const [a,b]=String(v).split('.').map(Number);return type==='major'?`${(a||0)+1}.0`:`${a||1}.${(b||0)+1}`; }
async function checkinDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d||d.checkedOutBy!==account.name)return;const type=$('#checkinType').value,summary=$('#changeSummary').value.trim()||'Controlled document update';d.version=nextVersion(d.version,type);d.versions.push({version:d.version,summary,content:d.content,at:nowISO(),by:account.name});d.checkedOutBy=null;d.status='Draft';await logEvent('Check In',d,{version:d.version,summary});persist();closeModal();toast(`Checked in as version ${d.version}`);render(); }
window.checkinDocument=checkinDocument;
function editDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canEditDocs())return;if(d.legalHold){toast('Legal hold prevents editing');return;}if(d.checkedOutBy!==account.name){toast('Check out the document before editing');return;}modal('Edit Controlled Document',`<div class="form-grid"><div class="field"><label>Document Title</label><input id="editTitle" value="${esc(d.title)}"></div><div class="field"><label>Classification</label><select id="editClass">${['Internal','Confidential','Restricted'].map(x=>`<option ${d.classification===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Multi-Section Authoring</label><div class="editor-toolbar"><button onclick="document.execCommand('bold')"><b>B</b></button><button onclick="document.execCommand('italic')"><i>I</i></button><button onclick="document.execCommand('formatBlock',false,'h2')">H2</button><button onclick="document.execCommand('insertUnorderedList')">• List</button></div><div class="editor" id="docEditor" contenteditable="true">${d.content}</div></div></div><div class="btn-row" style="justify-content:flex-end">${btn('Cancel','',"closeModal()")}${btn('Save Working Copy','primary',`saveDocumentEdit('${id}')`)}</div>`); }
window.editDocument=editDocument;
async function saveDocumentEdit(id){ const d=store.docs.find(x=>x.id===id);if(!d)return;d.title=$('#editTitle').value.trim()||d.title;d.classification=$('#editClass').value;d.content=$('#docEditor').innerHTML;await logEvent('Edit',d,{workingCopy:true});persist();closeModal();toast('Working copy saved. Check in to create a version.');render(); }
window.saveDocumentEdit=saveDocumentEdit;
async function submitApproval(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canEditDocs())return;if(d.checkedOutBy){toast('Check in the document before submitting');return;}d.status='Pending Approval';await logEvent('Submit for Approval',d,{workflow:'Owner → Compliance Approver'});persist();toast('Submitted to Sarah Jenkins for sequential approval');render(); }
window.submitApproval=submitApproval;
function createDocumentPage(){ if(!canEditDocs())return noAccess();return `${pageHead('Create Controlled Document','Direct multi-section manual authoring with metadata, classification, version 1.0 and governed lifecycle.',btn('Back to Library','',"go('documents')"))}<div class="grid two"><section class="card"><div class="card-head"><div><h3>Document Metadata</h3><p>Required governance attributes</p></div>${pill('Draft v1.0','blue')}</div><div class="card-body"><div class="form-grid"><div class="field full"><label>Document Title</label><input id="newDocTitle" value="Enterprise Business Continuity Policy"></div><div class="field"><label>Document Code</label><input id="newDocCode" value="POL-BCM-001"></div><div class="field"><label>Category</label><select id="newDocCategory"><option>Policy</option><option>Procedure</option><option>SOP</option><option>Guideline</option><option>Template</option><option>Evidence</option></select></div><div class="field"><label>Department</label><select id="newDocDept"><option>Information Security</option><option>Legal & Compliance</option><option>Risk</option><option>IT Operations</option><option>Internal Audit</option></select></div><div class="field"><label>Security Classification</label><select id="newDocClass"><option>Internal</option><option selected>Confidential</option><option>Restricted</option></select></div><div class="field"><label>Retention Schedule</label><select id="newDocRetention"><option>7 years after supersession</option><option>10 years</option><option>Contract + 10 years</option><option>Permanent</option></select></div><div class="field"><label>Review Date</label><input id="newDocReview" type="date" value="2027-07-24"></div><div class="field full"><label>Framework Mapping</label><input id="newDocFramework" value="ISO 22301, ISO 27001 A.5.29"></div></div></div></section><section class="card"><div class="card-head"><div><h3>Multi-Section Authoring</h3><p>Add headings, sections and governance requirements</p></div></div><div class="card-body"><div class="editor-toolbar"><button onclick="document.execCommand('bold')"><b>B</b></button><button onclick="document.execCommand('italic')"><i>I</i></button><button onclick="document.execCommand('formatBlock',false,'h2')">H2</button><button onclick="document.execCommand('insertUnorderedList')">• List</button></div><div class="editor" id="newDocEditor" contenteditable="true"><h2>1. Purpose</h2><p>Define the organization’s requirements for continuity and resilience.</p><h2>2. Scope</h2><p>This policy applies to critical business services, personnel, suppliers, technology and facilities.</p><h2>3. Governance Requirements</h2><p>Business impact analysis and recovery plans shall be reviewed and tested at planned intervals.</p></div><div class="btn-row top-gap" style="justify-content:flex-end">${btn('Save Draft v1.0','primary',"createDocument()")}</div></div></section></div>`; }
async function createDocument(){ const title=$('#newDocTitle').value.trim(),code=$('#newDocCode').value.trim().toUpperCase();if(!title||!code){toast('Title and document code are required');return;}if(store.docs.some(d=>d.code===code)){toast('Document code already exists');return;}const d={id:uid('DOC'),code,title,category:$('#newDocCategory').value,department:$('#newDocDept').value,classification:$('#newDocClass').value,owner:account.name,status:'Draft',version:'1.0',checkedOutBy:null,content:$('#newDocEditor').innerHTML,versions:[],approvals:[],acknowledgements:[],retention:$('#newDocRetention').value,legalHold:false,reviewDate:$('#newDocReview').value,frameworks:$('#newDocFramework').value.split(',').map(x=>x.trim()).filter(Boolean),createdAt:nowISO()};d.versions.push({version:'1.0',summary:'Initial controlled draft',content:d.content,at:d.createdAt,by:account.name});store.docs.unshift(d);store.selectedDoc=d.id;await logEvent('Create',d,{version:'1.0'});persist();toast('Document created as version 1.0');go('documents'); }
window.createDocument=createDocument;
function importDocumentsPage(){ if(!canEditDocs())return noAccess();return `${pageHead('Batch Document Import','Drag and drop one or more files. The mock stages metadata, category and generated codes before controlled import.',btn('Back to Library','',"go('documents')"))}<section class="card"><div class="card-body"><div class="dropzone" id="dropzone"><div><div class="big">⇧</div><h2>Drop files here</h2><p class="muted">PDF, DOCX, XLSX, TXT, MD, JSON and PNG</p><input id="fileInput" type="file" multiple accept=".pdf,.docx,.xlsx,.txt,.md,.json,.png" hidden><button class="btn primary" onclick="document.getElementById('fileInput').click()">Select Files</button></div></div><div id="stagedFiles" class="top-gap"></div><div class="notice top-gap">The production service should validate signatures and MIME types, quarantine files, run malware scanning, extract text in an isolated worker and encrypt objects before indexing.</div><div class="btn-row top-gap" style="justify-content:flex-end">${btn('Clear Staging','',"clearStagedFiles()")}${btn('Confirm & Import All','primary',"confirmImportAll()")}</div></div></section>`; }
function stageFiles(files){ const allowed=['pdf','docx','xlsx','txt','md','json','png'];[...files].forEach(f=>{const ext=(f.name.split('.').pop()||'').toLowerCase();if(!allowed.includes(ext)){toast(`Unsupported file: ${f.name}`);return;}const base=f.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ');store.stagedFiles.push({name:f.name,size:f.size||Math.floor(Math.random()*900000)+40000,type:ext,category:/policy/i.test(base)?'Policy':/procedure|sop/i.test(base)?'Procedure':/audit|report/i.test(base)?'Report':'Evidence',title:base.replace(/\b\w/g,c=>c.toUpperCase()),code:`${/policy/i.test(base)?'POL':/report|audit/i.test(base)?'RPT':'EVD'}-IMP-${String(store.docs.length+store.stagedFiles.length).padStart(3,'0')}`});});renderStaged(); }
function renderStaged(){ const el=$('#stagedFiles');if(!el)return;el.innerHTML=store.stagedFiles.length?`<h3 class="section-title">Staged Files (${store.stagedFiles.length})</h3>${store.stagedFiles.map((f,i)=>`<div class="file-chip"><div><strong>${esc(f.name)}</strong><div class="tiny muted">${(f.size/1024).toFixed(1)} KB · inferred ${f.category} · ${f.code}</div></div><button class="btn sm red" onclick="removeStagedFile(${i})">Remove</button></div>`).join('')}`:empty('No files staged','Select or drop supported files to begin.','⇧'); }
function removeStagedFile(i){store.stagedFiles.splice(i,1);renderStaged()} window.removeStagedFile=removeStagedFile;
function clearStagedFiles(){store.stagedFiles=[];renderStaged()} window.clearStagedFiles=clearStagedFiles;
async function confirmImportAll(){ if(!store.stagedFiles.length){toast('Stage at least one file');return;}for(const f of store.stagedFiles){const d={id:uid('DOC'),code:f.code,title:f.title,category:f.category,department:'Imported Repository',classification:'Internal',owner:account.name,status:'Draft',version:'1.0',checkedOutBy:null,content:`<h2>Imported Content</h2><p>Text extraction preview for <strong>${esc(f.name)}</strong>.</p><p>The production service would preserve the original file, extract searchable content, validate metadata and record an integrity hash.</p>`,versions:[],approvals:[],acknowledgements:[],retention:'7 years after supersession',legalHold:false,reviewDate:'2027-07-24',frameworks:[],createdAt:nowISO()};d.versions=[{version:'1.0',summary:`Imported from ${f.name}`,content:d.content,at:d.createdAt,by:account.name}];store.docs.unshift(d);await logEvent('Import',d,{sourceFile:f.name,size:f.size});}store.stagedFiles=[];persist();toast('All files imported as controlled version 1.0 records');go('documents'); }
window.confirmImportAll=confirmImportAll;
function versionControlPage(){ const docs=store.docs.filter(d=>(d.versions?.length||0)>0);return `${pageHead('Version Control','Compare immutable snapshots, inspect change summaries and restore a historical baseline as a new controlled version.',btn('Document Library','',"go('documents')"))}<section class="card"><div class="toolbar"><input placeholder="Search documents or versions"><select id="versionDocSelect" onchange="renderVersionDetails(this.value)">${docs.map(d=>`<option value="${d.id}" ${d.id===store.selectedDoc?'selected':''}>${esc(d.code)} — ${esc(d.title)}</option>`).join('')}</select><span class="spacer"></span>${pill('Semantic versioning','green')}</div><div id="versionDetails"></div></section>`; }
function renderVersionDetails(id){ const d=store.docs.find(x=>x.id===id)||selectedDoc();if(!d)return;store.selectedDoc=d.id;persist();const versions=[...(d.versions||[])].reverse();const el=$('#versionDetails');if(!el)return;el.innerHTML=`<div class="grid two" style="padding:14px"><div>${table(['Version','Summary','Created','By','Actions'],versions.map((v,i)=>`<tr><td>${pill('v'+v.version,i===0?'green':'blue')}</td><td>${esc(v.summary)}</td><td>${dateFmt(v.at)}</td><td>${esc(v.by)}</td><td><div class="btn-row">${btn('Preview','sm',`previewVersion('${d.id}','${v.version}')`)}${i<versions.length-1&&canEditDocs()?btn('Restore','sm amber',`restoreVersion('${d.id}','${v.version}')`):''}</div></td></tr>`))}</div><div class="card"><div class="card-head"><div><h3>Side-by-Side Difference</h3><p>Latest version compared with prior baseline</p></div>${pill(`${versions.length} snapshots`,'blue')}</div><div class="card-body">${versionDiff(d)}</div></div></div>`; }
function versionDiff(d){ const a=d.versions?.[d.versions.length-2],b=d.versions?.[d.versions.length-1];if(!a||!b)return empty('One version only','Create a new version to enable comparison.','⌁');return `<div class="diff"><div class="diff-pane"><strong>v${a.version}</strong><hr>${a.content}</div><div class="diff-pane"><strong>v${b.version}</strong><hr>${b.content}<p class="diff-add">Change summary: ${esc(b.summary)}</p></div></div>`; }
function previewVersion(id,v){const d=store.docs.find(x=>x.id===id),ver=d?.versions.find(x=>x.version===v);if(!ver)return;modal(`${d.code} · Version ${v}`,`<div class="preview-sheet"><div class="watermark">HISTORICAL VERSION</div><h1>${esc(d.title)}</h1><p style="text-align:center">Version ${v} · ${dateFmt(ver.at)} · ${esc(ver.by)}</p><hr>${ver.content}</div>`)} window.previewVersion=previewVersion;
async function restoreVersion(id,v){const d=store.docs.find(x=>x.id===id),ver=d?.versions.find(x=>x.version===v);if(!d||!ver||!canEditDocs())return;if(d.legalHold){toast('Legal hold prevents restoration');return;}const newV=nextVersion(d.version,'minor');d.content=ver.content;d.version=newV;d.status='Draft';d.versions.push({version:newV,summary:`Restored baseline from v${v}`,content:ver.content,at:nowISO(),by:account.name});await logEvent('Restore Version',d,{sourceVersion:v,newVersion:newV});persist();toast(`Version ${v} restored as new version ${newV}`);renderVersionDetails(id)} window.restoreVersion=restoreVersion;
function approvalsPage(){ const q=store.docs.filter(d=>['Pending Approval','Under Review'].includes(d.status));if(!canApproveDocs()&&account.role!=='Compliance Manager'&&!['Group Admin','Organization Admin'].includes(account.role))return noAccess();return `${pageHead('Sequential Approval Workflow','Review content, comments, version history and apply cryptographic e-signatures with segregation of duties.',btn('Workflow Configuration','',"toast('Approval workflow configuration opened')"))}<div class="workflow"><div class="workflow-step done">Draft</div><div class="workflow-arrow">→</div><div class="workflow-step done">Under Review</div><div class="workflow-arrow">→</div><div class="workflow-step active">Pending Approval</div><div class="workflow-arrow">→</div><div class="workflow-step">Published</div></div><div class="grid kpi">${kpi('Pending Approval',q.length,'Assigned queue','✓','amber')}${kpi('Approved This Month','6','Digital signatures recorded','#','green')}${kpi('Returned','1','Owner action required','↩','red')}${kpi('Approval SLA','96%','Target 95%','◷','blue')}</div><section class="card top-gap">${q.length?table(['Document','Version','Owner','Classification','Submitted','Status','Action'],q.map(d=>`<tr><td><div class="title">${esc(d.title)}</div><div class="sub mono">${d.code}</div></td><td>${d.version}</td><td>${esc(d.owner)}</td><td>${statusPill(d.classification)}</td><td>${dateFmt(store.logs.find(l=>l.document===d.code&&l.event==='Submit for Approval')?.at||d.createdAt)}</td><td>${statusPill(d.status)}</td><td>${canApproveDocs()?btn('Review & Sign','sm primary',`reviewApproval('${d.id}')`):btn('Track','sm',`previewDocument('${d.id}')`)}</td></tr>`)):empty('Approval queue is clear','There are no pending documents.')}</section>`; }
function reviewApproval(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canApproveDocs())return;modal('Review & Cryptographically Sign',`<div class="notice">Segregation of duties is enforced: the current approver is different from the document owner. Signing will publish the approved version and create immutable evidence.</div><div class="grid two top-gap"><div class="preview-sheet" style="min-height:420px;padding:28px"><div class="watermark">APPROVAL REVIEW</div><div class="tiny mono muted" style="text-align:center">${d.code} · v${d.version}</div><h1>${esc(d.title)}</h1>${d.content}</div><div><div class="meta-grid">${meta('Owner',esc(d.owner))}${meta('Approver',esc(account.name))}${meta('Role',esc(account.role))}${meta('Version',d.version)}${meta('Classification',esc(d.classification))}${meta('Session',uid('SES'))}</div><div class="field top-gap"><label>Approval Comment</label><textarea id="approvalComment">Reviewed for compliance, governance and publication readiness.</textarea></div><div class="field"><label>E-Signature (type full name)</label><input id="approvalSignature" placeholder="${esc(account.name)}"></div><div class="notice amber">The system will record ISO 8601 timestamp, role, IP address, session token and a SHA-256 verification hash.</div><div class="btn-row top-gap">${btn('Return to Owner','red',`returnDocument('${id}')`)}${btn('Approve & Sign','primary',`approveDocument('${id}')`)}</div></div></div>`); }
window.reviewApproval=reviewApproval;
async function approveDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canApproveDocs())return;if(d.owner===account.name){toast('Segregation of duties prevents self-approval');return;}const sig=$('#approvalSignature').value.trim();if(sig!==account.name){toast('Type the approver full name exactly');return;}const at=nowISO(),ip=`10.42.8.${20+Math.floor(Math.random()*20)}`,session=uid('SES-APP');const hash=await sha256(`${d.code}|${d.version}|${d.content}|${account.name}|${account.role}|${at}|${ip}|${session}`);d.approvals.push({name:account.name,role:account.role,at,ip,session,hash,comment:$('#approvalComment').value.trim()});d.status='Published';await logEvent('Approve',d,{version:d.version,signatureHash:hash,session});persist();closeModal();toast('Approved, digitally signed and published');render(); }
window.approveDocument=approveDocument;
async function returnDocument(id){const d=store.docs.find(x=>x.id===id);if(!d||!canApproveDocs())return;d.status='Draft';await logEvent('Reject / Return',d,{comment:$('#approvalComment')?.value||'Returned for revision'});persist();closeModal();toast('Document returned to owner for revision');render()} window.returnDocument=returnDocument;
function acknowledgementsPage(){ const docs=store.docs.filter(d=>d.status==='Published');const isStaff=canAcknowledge();return `${pageHead('Mandatory Acknowledgements',isStaff?'Read assigned policies and provide a digital acknowledgement signature.':'Monitor distribution, completion, reminders and overdue sign-offs.',!isStaff?btn('Assign Policy','primary',"openSimpleForm('Assign Policy Acknowledgement','assignment')")+btn('Send Reminders','',"toast('Reminder emails logged and queued')"):'')}<div class="grid kpi">${kpi('Published Policies',docs.length,'Available for distribution','▤','blue')}${kpi('Accepted Rate','91%','Across assigned audience','✓','green')}${kpi('Pending Sign-Offs',isStaff?docs.filter(d=>!d.acknowledgements?.some(a=>a.email===account.email)).length:73,'Reminder workflow active','✎','amber')}${kpi('Overdue','12','Managers notified','!','red')}</div><div class="grid three top-gap">${docs.map(d=>ackCard(d,isStaff)).join('')}</div>`; }
function ackCard(d,isStaff=canAcknowledge()){ const done=d.acknowledgements?.some(a=>a.email===account.email);return `<div class="ack-card"><div class="split"><div class="doc-icon">POL</div>${done?statusPill('Acknowledged'):statusPill('Pending')}</div><h3>${esc(d.title)}</h3><p>${d.code} · v${d.version} · ${d.classification}</p><div class="ack-stat"><span>${d.acknowledgements?.length||0} recorded</span><span>Due 31 Aug 2026</span></div><div class="btn-row top-gap">${btn('Read','sm',`previewDocument('${d.id}')`)}${isStaff&&!done?btn('Sign Acknowledgement','sm primary',`acknowledgeDocument('${d.id}')`):!isStaff?btn('Completion','sm',"toast('Audience completion report opened')"):''}</div></div>`; }
function acknowledgeDocument(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canAcknowledge()||d.status!=='Published')return;modal('Mandatory Policy Acknowledgement',`<div class="notice">Read the controlled policy before signing. Your acknowledgement records identity, timestamp, session and verification hash.</div><div class="preview-sheet top-gap" style="min-height:360px;padding:28px"><h1>${esc(d.title)}</h1><p style="text-align:center">${d.code} · v${d.version}</p>${d.content}</div><div class="form-grid top-gap"><div class="field"><label>Digital Signature</label><input id="ackSignature" placeholder="${esc(account.name)}"></div><div class="field"><label>Confirmation</label><select id="ackConfirm"><option value="">Select confirmation</option><option value="yes">I have read and understood this policy</option></select></div></div><div class="btn-row" style="justify-content:flex-end">${btn('Cancel','',"closeModal()")}${btn('Submit Acknowledgement','primary',`submitAcknowledgement('${id}')`)}</div>`); }
window.acknowledgeDocument=acknowledgeDocument;
async function submitAcknowledgement(id){ const d=store.docs.find(x=>x.id===id);if(!d||!canAcknowledge())return;if($('#ackSignature').value.trim()!==account.name||$('#ackConfirm').value!=='yes'){toast('Enter your full name and confirm understanding');return;}if(d.acknowledgements.some(a=>a.email===account.email)){toast('Already acknowledged');return;}const at=nowISO(),hash=await sha256(`${d.code}|${d.version}|${account.email}|${at}`);d.acknowledgements.push({name:account.name,email:account.email,at,signature:account.name,hash});await logEvent('Acknowledge',d,{signatureHash:hash});persist();closeModal();toast('Acknowledgement recorded');render(); }
window.submitAcknowledgement=submitAcknowledgement;
function retentionPage(){ if(!canApproveDocs()&&!canEditDocs())return noAccess();return `${pageHead('Retention & Legal Holds','Apply lifecycle schedules, disposition review and one-click WORM legal holds.',btn('Create Retention Rule','primary',"openSimpleForm('Create Retention Rule','retention')")+btn('Run Disposition Review','',"toast('Disposition review started')"))}<div class="grid kpi">${kpi('Retention Schedules','18','Data class and jurisdiction aware','♜','blue')}${kpi('Documents on Hold',store.docs.filter(d=>d.legalHold).length,'Disposal suspended','⚑','red')}${kpi('Disposition Queue','37','Dual approval required','◷','amber')}${kpi('Deletion Evidence','100%','Verified and logged','✓','green')}</div><section class="card top-gap">${table(['Document','Category','Retention Schedule','Review','Legal Hold','Lifecycle Action'],store.docs.map(d=>`<tr><td><div class="title">${esc(d.title)}</div><div class="sub mono">${d.code}</div></td><td>${d.category}</td><td>${esc(d.retention)}</td><td>${esc(d.reviewDate)}</td><td>${d.legalHold?statusPill('WORM Hold'):statusPill('No Hold')}</td><td><div class="btn-row">${btn(d.legalHold?'Release Hold':'Apply Legal Hold',`sm ${d.legalHold?'amber':'red'}`,`toggleLegalHold('${d.id}')`)}${btn('Edit Schedule','sm',"toast('Retention schedule editor opened')")}</div></td></tr>`))}</section><div class="legal-hold top-gap"><strong>Legal Hold Protection</strong><p>When a hold is active, editing, version restoration, automated archive and disposal are suspended. Releasing a hold creates an immutable event and resumes the approved lifecycle schedule.</p></div>`; }
async function toggleLegalHold(id){ const d=store.docs.find(x=>x.id===id);if(!d)return;const action=d.legalHold?'Release Legal Hold':'Apply Legal Hold';if(!confirm(`${action} for ${d.code}?`))return;d.legalHold=!d.legalHold;await logEvent(d.legalHold?'Legal Hold':'Release Hold',d,{worm:d.legalHold});persist();toast(d.legalHold?'Document frozen in WORM status':'Legal hold released');render(); }
window.toggleLegalHold=toggleLegalHold;
function activityLogsPage(){ const readOnly=isAuditor();return `${pageHead('Immutable Activity Logs','Verifiable event history for create, edit, import, check-out, check-in, approval, acknowledgement and legal hold.',btn('Export Audit Log','primary',"exportLogs()"))}<div class="grid kpi">${kpi('Logged Events',store.logs.length,'Prototype event store','≡','blue')}${kpi('Hash Coverage','100%','SHA-256 or deterministic fallback','#','green')}${kpi('Personas Recorded',new Set(store.logs.map(l=>l.role)).size,'Identity and role','♙','violet')}${kpi('Tamper Alerts','0','All current events verified','✓','green')}</div><section class="card top-gap"><div class="toolbar"><input id="logSearch" placeholder="Search event, document or user"><select><option>All event types</option><option>Create</option><option>Edit</option><option>Approve</option><option>Acknowledge</option><option>Legal Hold</option></select><span class="spacer"></span>${readOnly?pill('Auditor read-only','violet'):pill('Protected history','green')}</div>${table(['Event','Document','User & Persona','Timestamp / Origin','Verification Hash'],store.logs.map(l=>`<tr><td>${statusPill(l.event)}</td><td class="mono">${esc(l.document)}</td><td><div class="title">${esc(l.user)}</div><div class="sub">${esc(l.role)}</div></td><td><div>${dateFmt(l.at)}</div><div class="sub">${esc(l.ip||'10.42.0.1')}</div></td><td><div class="audit-hash mono">${esc(l.hash)}</div><button class="btn sm" onclick="verifyLog('${l.id}')">Verify</button></td></tr>`))}</section>`; }
function verifyLog(id){ const l=store.logs.find(x=>x.id===id);if(!l)return;modal('Hash Verification',`<div class="signature-card"><strong>${esc(l.event)} · ${esc(l.document)}</strong><div class="tiny muted">${esc(l.user)} · ${dateFmt(l.at)} · ${esc(l.ip||'network origin recorded')}</div><div class="hash">${esc(l.hash)}</div></div><div class="notice top-gap">Verification result: the event has a well-formed cryptographic integrity record and is present in the protected audit sequence.</div>`); }
window.verifyLog=verifyLog;
function exportLogs(){ const blob=new Blob([JSON.stringify(store.logs,null,2)],{type:'application/json'});downloadBlob(blob,'grc-wisdom-activity-log.json');toast('Activity log exported'); } window.exportLogs=exportLogs;
function auditorPackagePage(){ const docs=store.docs.filter(d=>d.status==='Published');return `${pageHead('Evidence Package','Approved documents, signatures, evidence and retention metadata within the external audit scope.',btn('Export Package Manifest','primary',"exportAuditPackage()"))}<div class="notice">External Auditor access is temporary, read-only and engagement-scoped. Downloads should be controlled, watermarked and logged in production.</div><section class="card top-gap">${table(['Artifact','Version','Owner','Classification','Signature','Retention','Hold','Action'],docs.map(d=>`<tr><td><div class="title">${esc(d.title)}</div><div class="sub mono">${d.code}</div></td><td>${d.version}</td><td>${esc(d.owner)}</td><td>${statusPill(d.classification)}</td><td>${d.approvals?.length?statusPill('Verified'):statusPill('No Signature')}</td><td>${esc(d.retention)}</td><td>${d.legalHold?statusPill('WORM'):statusPill('No')}</td><td>${btn('Inspect','sm',`previewDocument('${d.id}')`)}</td></tr>`))}</section>`; }
function hashVerificationPage(){ return `${pageHead('Hash Verification','Validate approval signatures, acknowledgements and immutable activity records without changing source artifacts.')}<div class="grid two"><section class="card pad"><h3 class="section-title">Verify a document signature</h3><div class="field"><label>Published Document</label><select id="hashDoc">${store.docs.filter(d=>d.status==='Published').map(d=>`<option value="${d.id}">${esc(d.code)} — ${esc(d.title)}</option>`).join('')}</select></div><button class="btn primary" onclick="verifyDocumentSignature()">Verify Signature</button><div id="hashResult" class="top-gap"></div></section><section class="card pad"><h3 class="section-title">Verification controls</h3><div class="score-list">${[['SHA-256 format',100],['Signer identity captured',100],['Version binding',100],['Timestamp captured',100],['Network origin captured',100],['Session token captured',100]].map(x=>`<div class="score-row"><span>${x[0]}</span>${progress(x[1])}<strong>${x[1]}%</strong></div>`).join('')}</div></section></div>`; }
function verifyDocumentSignature(){ const d=store.docs.find(x=>x.id===$('#hashDoc').value),a=d?.approvals?.[d.approvals.length-1];$('#hashResult').innerHTML=a?`<div class="signature-card"><strong>Verified: ${esc(d.code)} v${d.version}</strong><div class="tiny muted">Signed by ${esc(a.name)} (${esc(a.role)}) · ${dateFmt(a.at)}</div><div class="hash">${esc(a.hash)}</div></div><div class="notice top-gap">The signature record is present and bound to the approved document version in this prototype.</div>`:`<div class="notice amber">No approval signature is recorded for this artifact.</div>`; }
window.verifyDocumentSignature=verifyDocumentSignature;
function exportAuditPackage(){ const manifest={generatedAt:nowISO(),generatedBy:account.email,engagement:'Global Bank ISO 27001 Audit Room',access:'Read-only',documents:store.docs.filter(d=>d.status==='Published').map(d=>({code:d.code,title:d.title,version:d.version,classification:d.classification,owner:d.owner,retention:d.retention,legalHold:d.legalHold,signature:d.approvals?.at(-1)||null})),logs:store.logs};downloadBlob(new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'}),'GRC_Wisdom_Audit_Package_Manifest.json');toast('Audit package manifest exported'); }
window.exportAuditPackage=exportAuditPackage;
function auditorExportPage(){ return `${pageHead('Audit Export','Prepare a controlled exit package with manifest, signature hashes, retention status and immutable activity history.',btn('Download JSON Manifest','primary',"exportAuditPackage()"))}<div class="grid three">${['Controlled Document Index','Approval Signature Register','Version Lineage','Retention & Legal Hold Register','Immutable Activity Log','Evidence Mapping Summary'].map((x,i)=>`<div class="card pad"><div class="split"><div class="kpi-icon" style="--icon-color:${iconColor(i)}">${['▤','#','⌁','♜','≡','⌘'][i]}</div>${statusPill('Ready')}</div><h3>${x}</h3><p class="small muted">Included in the read-only audit package with generation metadata and verification references.</p></div>`).join('')}</div><div class="notice top-gap">Production exports should apply scope authorization, watermarking, encryption, time-limited download URLs and an export reconciliation report.</div>`; }
function impersonationPage(){ return `${pageHead('Impersonation Sessions','Controlled break-glass support access with customer authorization, time limits, reason and immutable evidence.',btn('Request Session','primary',"openSimpleForm('Request Impersonation Session','impersonation')"))}<div class="notice red"><strong>No routine customer-data access.</strong> Platform administrators must obtain explicit approval and use time-bound, reason-coded break-glass sessions.</div><section class="card top-gap">${table(['Session','Tenant','Requested By','Approved By','Purpose','Started','Expires','Status'],[['IMP-2026-041','OmniOps','Support Engineer','Fadi Ibrahim','Report rendering issue','22 Jul 10:15','22 Jul 10:45','Completed'],['IMP-2026-040','Hayat National Hospitals','Security Admin','Nizar Al-Saqqaf','Investigate login alert','20 Jul 13:00','20 Jul 13:20','Completed'],['IMP-2026-039','Eteqan Projects','Customer Success','Awais Ahmed','Onboarding assistance','19 Jul 09:10','19 Jul 09:40','Completed']].map(x=>`<tr>${x.map((v,i)=>`<td>${i===0?`<span class="mono">${v}</span>`:i===7?statusPill(v):v}</td>`).join('')}</tr>`))}</section>`; }
