 const invs=visibleInvoices();return `${pageHead('Invoice Management','Generate ZATCA-ready mock invoices, apply VAT, allocate services, collect payment and preserve receipt history.',account.portal==='saas'?btn('Generate Invoice','primary',"openInvoiceBuilder()"):btn('Billing Center','',"go('billing-center')"))}<div class="grid kpi">${kpi('Invoices',invs.length,'Current visible scope','▤','blue')}${kpi('Paid',invs.filter(i=>i.status==='Paid').length,'Fully reconciled','✓','green')}${kpi('Pending',invs.filter(i=>i.status==='Pending').length,'Within terms','◷','amber')}${kpi('Overdue',invs.filter(i=>i.status==='Overdue').length,'Escalation active','!','red')}</div><section class="card top-gap">${table(['Invoice','Customer','Issue / Due','Subtotal','VAT','Total','Balance','Status','Action'],invs.map(i=>{const t=invoiceTotals(i);return `<tr><td><div class="title mono">${i.id}</div><div class="sub">${esc(i.po||'No PO')}</div></td><td>${esc(i.customer)}</td><td>${i.issueDate}<div class="sub">${i.dueDate}</div></td><td>${money(t.subtotal)}</td><td>${money(t.vat)}</td><td><strong>${money(t.total)}</strong></td><td>${money(t.balance)}</td><td>${statusPill(i.status)}</td><td><div class="btn-row">${btn('View','sm',`viewInvoice('${i.id}')`)}${t.balance>0?btn('Pay / Record','sm primary',`openPayment('${i.id}')`):btn('Receipt','sm',"toast('Payment receipt opened')")}</div></td></tr>`}) )}</section>`;
