async function saveInvoice(){const i={id:`INV-${new Date().getFullYear()}-${String(store.invoicesV3.length+87).padStart(4,'0')}`,context:$('#invContext').value.trim()||$('#invCustomer').value.trim(),customer:$('#invCustomer').value.trim()||'New Customer',issueDate:new Date().toISOString().slice(0,10),dueDate:$('#invDue').value,currency:'SAR',status:'Pending',po:$('#invPO').value.trim(),lines:[{description:$('#invDesc').value,qty:+$('#invQty').value||1,unit:+$('#invUnit').value||0}],vatRate:+$('#invVat').value,payments:[]};store.invoicesV3.push(i);await logEvent('Generate Invoice',i.id,{customer:i.customer,total:invoiceTotals(i).total});persist();closeModal();toast(`${i.id} generated`);render()}
