function viewInvoice(id){const i=store.invoicesV3.find(x=>x.id===id);if(!i)return;const t=invoiceTotals(i);modal(`Invoice ${i.id}`,`<div class="invoice-sheet"><div class="invoice-head"><div><h2>GRC Wisdom</h2><span>Beginning Solutions IT Est. · Saudi Arabia</span></div><div><strong>TAX INVOICE</strong><span>${i.id}</span></div></div><div class="meta-grid">${meta('Bill To',esc(i.customer))}${meta('PO / Contract',esc(i.po||'—'))}${meta('Issue Date',i.issueDate)}${meta('Due Date',i.dueDate)}</div>${table(['Description','Qty','Unit Price','Line Total'],i.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.qty}</td><td>${money(l.unit)}</td><td>${money(l.qty*l.unit)}</td></tr>`))}<div class="invoice-totals"><span>Subtotal <strong>${money(t.subtotal)}</strong></span><span>VAT ${i.vatRate}% <strong>${money(t.vat)}</strong></span><span class="grand">Total <strong>${money(t.total)}</strong></span><span>Paid <strong>${money(t.paid)}</strong></span><span>Balance <strong>${money(t.balance)}</strong></span></div><div class="tiny muted">Mock invoice for product visualization. Production requires legal entity, VAT registration, QR/e-invoicing and gateway integration.</div></div><div class="btn-row top-gap" style="justify-content:flex-end">${btn('Download HTML Invoice','',`downloadInvoice('${id}')`)}${t.balance>0?btn('Pay / Record Payment','primary',`closeModal();openPayment('${id}')`):btn('Close','primary',"closeModal()")}</div>`)}
