function downloadInvoice(id){const i=store.invoicesV3.find(x=>x.id===id);if(!i)return;const t=invoiceTotals(i),html=`<!doctype html><html><head><meta charset="utf-8"><title>${i.id}</title><style>body{font-family:Arial;margin:40px;color:#172033}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{border:1px solid #ddd;padding:10px;text-align:left}.totals{text-align:right;font-size:18px}</style></head><body><h1>GRC Wisdom — Tax Invoice</h1><p><strong>${i.id}</strong></p><p>Bill to: ${esc(i.customer)}<br>Issue: ${i.issueDate}<br>Due: ${i.dueDate}</p><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr>${i.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.qty}</td><td>${money(l.unit)}</td><td>${money(l.qty*l.unit)}</td></tr>`).join('')}</table><div class="totals">Subtotal ${money(t.subtotal)}<br>VAT ${money(t.vat)}<br><strong>Total ${money(t.total)}</strong><br>Balance ${money(t.balance)}</div></body></html>`;downloadBlob(new Blob([html],{type:'text/html'}),`${i.id}.html`);toast('Invoice downloaded')}
